    /**
     * Tests getting all ReturnRequests.
     *
     * @return    Collection
     */
    public List<ReturnRequest> testGetAll() throws Throwable {
    LOGGER.info( "ReturnRequestTest:testGetAll() - Retrieving Collection of ReturnRequests:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all ReturnRequest : " );
    List<ReturnRequest> collection  = null;

    try {
        // call the static get method on the ReturnRequestService
        collection = service.getAllReturnRequest();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            ReturnRequest currEntity  = null;
            Iterator<ReturnRequest> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getReturnRequestId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

